package com.huy.enterprise.inventory;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class WarehouseService{private final WarehouseRepository repository; public List<WarehouseResponse> all(){return repository.findAll().stream().map(WarehouseResponse::from).toList();} public WarehouseResponse one(UUID id){return WarehouseResponse.from(get(id));}
@Transactional public WarehouseResponse create(WarehouseRequest r){if(repository.existsByWarehouseCode(r.warehouseCode()))throw new ConflictException("Warehouse code already exists: "+r.warehouseCode());Warehouse w=new Warehouse();w.setWarehouseCode(r.warehouseCode());apply(w,r);return WarehouseResponse.from(repository.save(w));}
@Transactional public WarehouseResponse update(UUID id,WarehouseRequest r){Warehouse w=get(id);if(!w.getWarehouseCode().equals(r.warehouseCode())&&repository.existsByWarehouseCode(r.warehouseCode()))throw new ConflictException("Warehouse code already exists: "+r.warehouseCode());w.setWarehouseCode(r.warehouseCode());apply(w,r);return WarehouseResponse.from(repository.save(w));} private Warehouse get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found: "+id));} private void apply(Warehouse w,WarehouseRequest r){w.setName(r.name());w.setAddress(r.address());w.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());}}
